Registro Product
  Definir name Como Cadena;
  Definir price Como Entero;
FinRegistro

Algoritmo Line
  Definir name Como Cadena;
  Definir price, quantity Como Entero;
  Leer name;
  Leer price;
  Leer quantity;
  Definir product Como Product <- Product(name, price);
  Escribir product.name, " x ", quantity, " = ", product.price * quantity;
FinAlgoritmo
